// Throwaway: the two-canvas spike's host. GPUI paints first (its title,
// time control, and the table's handle, over a dark page); the scene's
// module (Three.js) and the elements load after its first frame.
import { boot } from '@seiza/web/bootstrap';
import fontUrl from '@seiza/web/fonts/IBMPlexSans-Regular.ttf?url';
// Generated by wasm-bindgen into pkg/ (gitignored); `run.ts` builds it.
import init, { clock_moves, elements_ptr, load_elements, scene_years, spike_state, start } from '../pkg/kirkwood_spike.js';
import wasmUrl from '../pkg/kirkwood_spike_bg.wasm?url';
import { compositeByAlpha } from './alpha.ts';
import type { BeltScene } from './scene.ts';

type Kirkwood = {
  /** Called by the crate: a wheel over the scene. */
  wheel(x: number, y: number, delta: number): void;
  /** Called by the crate once GPUI's first frame is on screen. */
  firstFrame(): void;
  /** For `run.ts`. */
  scene?: BeltScene;
  state(): number[];
  alpha: boolean;
};

let memory: WebAssembly.Memory | undefined;
let scene: BeltScene | undefined;

async function afterFirstFrame(): Promise<void> {
  const [{ startScene }, response] = await Promise.all([import('./scene.ts'), fetch('/elements.bin')]);
  scene = startScene(document.querySelector<HTMLCanvasElement>('#scene')!, { years: scene_years, moves: clock_moves });
  kirkwood.scene = scene;
  performance.mark('kirkwood:scene');
  if (!response.ok) throw new Error(`elements.bin: ${response.status} (run data.ts)`);
  const rows = load_elements(new Uint8Array(await response.arrayBuffer()));
  // A view over the crate's own buffer: no copy on this side. Made after
  // `load_elements` returned and uploaded before anything else runs
  // (`setElements` draws), since the memory growing would detach it.
  scene.setElements(new Float32Array(memory!.buffer, elements_ptr(), rows * 6), rows);
  performance.mark('kirkwood:belt');
}

const kirkwood: Kirkwood = {
  wheel: (x, y, delta) => scene?.wheel(x, y, delta),
  firstFrame: () => void afterFirstFrame(),
  state: () => Array.from(spike_state()),
  alpha: compositeByAlpha(),
};
(globalThis as unknown as { __kirkwood: Kirkwood }).__kirkwood = kirkwood;
(globalThis as unknown as { __seizaFrameSample: () => object }).__seizaFrameSample = () => ({ scene: scene?.stats.frames ?? 0 });

void boot({
  init: async () => {
    memory = (await init({ module_or_path: wasmUrl })).memory;
  },
  start,
  fontUrl,
  wasmUrl,
});
